	// presence
	bool hasAnySet() const noexcept {
		for (std::size_t i = 0; i < NWORDS; ++i) {
			if (m_presence[i] != 0) { return true; }
		}
		if (m_Parties.hasAnySet()) { return true; }
		if (m_ContraGrp.hasAnySet()) { return true; }
		if (m_Instrument.hasAnySet()) { return true; }
		if (m_FinancingDetails.hasAnySet()) { return true; }
		if (m_UndInstrmtGrp.hasAnySet()) { return true; }
		if (m_Stipulations.hasAnySet()) { return true; }
		if (m_OrderQtyData.hasAnySet()) { return true; }
		if (m_PegInstructions.hasAnySet()) { return true; }
		if (m_DiscretionInstructions.hasAnySet()) { return true; }
		if (m_CommissionData.hasAnySet()) { return true; }
		if (m_SpreadOrBenchmarkCurveData.hasAnySet()) { return true; }
		if (m_YieldData.hasAnySet()) { return true; }
		if (m_ContAmtGrp.hasAnySet()) { return true; }
		if (m_InstrmtLegExecGrp.hasAnySet()) { return true; }
		if (m_MiscFeesGrp.hasAnySet()) { return true; }
		return false;
	}
